import 'dart:convert';
import 'dart:io';

/// Syncs [version_config.json] into Dart/Gradle files and optionally bumps the version.
///
/// Usage:
///   dart run tool/bump_version.dart --sync      # write generated files (no bump)
///   dart run tool/bump_version.dart --increment # bump version for next build
void main(List<String> args) {
  final projectRoot = _findProjectRoot();
  final configFile = File('${projectRoot.path}/version_config.json');
  if (!configFile.existsSync()) {
    stderr.writeln('version_config.json not found at ${configFile.path}');
    exit(1);
  }

  final config =
      jsonDecode(configFile.readAsStringSync()) as Map<String, dynamic>;
  final buildVersion = config['buildVersion'] as String;
  final isProduction = _readIsProduction(projectRoot);

  _writeGeneratedDart(projectRoot, buildVersion);
  _writeGradleProperties(projectRoot, buildVersion, isProduction);

  if (args.contains('--increment')) {
    final next = _incrementVersion(buildVersion);
    config['buildVersion'] = next;
    configFile.writeAsStringSync(
      const JsonEncoder.withIndent('  ').convert(config) + '\n',
    );
    stdout.writeln('Build version bumped: $buildVersion -> $next');
  } else {
    stdout.writeln('Build version synced: $buildVersion');
  }
}

Directory _findProjectRoot() {
  var dir = Directory.current;
  while (true) {
    if (File('${dir.path}/pubspec.yaml').existsSync()) {
      return dir;
    }
    final parent = dir.parent;
    if (parent.path == dir.path) {
      stderr.writeln('Could not find Flutter project root (pubspec.yaml).');
      exit(1);
    }
    dir = parent;
  }
}

bool _readIsProduction(Directory projectRoot) {
  final appConfig =
      File('${projectRoot.path}/lib/core/config/app_config.dart');
  final content = appConfig.readAsStringSync();
  final match = RegExp(r"baseDomain\s*=\s*'([^']+)'").firstMatch(content);
  return match != null && match.group(1)!.contains('prod.');
}

String _incrementVersion(String version) {
  final parts = version.split('.');
  if (parts.length != 2) {
    stderr.writeln('Invalid buildVersion format: $version (expected x.xx)');
    exit(1);
  }

  var major = int.parse(parts[0]);
  var minor = int.parse(parts[1]);

  if (minor < 99) {
    minor++;
  } else {
    major++;
    minor = 1;
  }

  return '$major.${minor.toString().padLeft(2, '0')}';
}

void _writeGeneratedDart(Directory projectRoot, String buildVersion) {
  final generatedDir = Directory('${projectRoot.path}/lib/generated');
  if (!generatedDir.existsSync()) {
    generatedDir.createSync(recursive: true);
  }

  final file = File('${generatedDir.path}/build_version.dart');
  file.writeAsStringSync('''// GENERATED by tool/bump_version.dart — do not edit manually.
class BuildVersion {
  static const String value = '$buildVersion';
}
''');
}

void _writeGradleProperties(
  Directory projectRoot,
  String buildVersion,
  bool isProduction,
) {
  final flavor = isProduction ? 'prod' : 'dev';
  final file = File('${projectRoot.path}/android/app/version.properties');
  file.writeAsStringSync('''# GENERATED by tool/bump_version.dart — do not edit manually.
buildVersion=$buildVersion
appFlavor=$flavor
''');
}
